/**
 * src/app/index.tsx
 *
 * Placeholder entry screen. Milestone 2 replaces it with the startup gate that
 * routes to the auth stack or the main tabs. Until then, development builds
 * show a button to the design gallery; release builds show a blank screen.
 */

import { useRouter, type Href } from 'expo-router';

import { Button, Screen } from '@/components/ui';

// The typed-routes file (.expo/types/router.d.ts) is regenerated by the dev
// server and can be stale right after a new route file is added, so the new
// '/gallery' route is cast once here. The cast is harmless once types refresh.
const GALLERY_HREF = '/gallery' as Href;

export default function IndexScreen() {
  const router = useRouter();

  return (
    <Screen contentStyle={{ justifyContent: 'center' }}>
      {__DEV__ ? <Button label="Open design gallery" onPress={() => router.push(GALLERY_HREF)} /> : null}
    </Screen>
  );
}
